         value: "Email",
         label: "Email",
         description: "Receive updates in your inbox."
       },
       {
         id: "notify-sms",
         value: "SMS",
         label: "SMS",
         description: "Get text alerts on your mobile device."
       },
       {
         id: "notify-push",
         value: "Push Notifications",
         label: "Push Notifications",
         description: "See instant updates in the app."
       }
     ];

     function RadioOption(option) {
       return `
         <label class="radio-option" for="${option.id}">
           <input id="${option.id}" type="radio" name="notificationPreference" value="${option.value}" required>
           <span class="radio-copy">
             <span class="radio-label">${option.label}</span>
             <span class="radio-description">${option.description}</span>
           </span>
         </label>
       `;
     }

     function NotificationPreferenceField() {
       return `
         <div class="form-field">
           <fieldset id="notification-group" aria-describedby="notification-help notification-error">
             <legend>
               How do you prefer to receive notifications?
               <span class="required-indicator" aria-hidden="true">*</span>
             </legend>
             <p id="notification-help" class="field-help">Choose one option so we know where to send product updates.</p>
             <div class="radio-grid">
               ${notificationOptions.map(RadioOption).join("")}
             </div>
           </fieldset>
           <p id="notification-error" class="field-error" hidden>Error: Select one notification preference.</p>
         </div>
       `;
     }

     function SettingsForm() {
       return `
         <form id="preferences-form" novalidate>
           <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required field</p>
           ${NotificationPreferenceField()}
           <div class="actions">
             <button class="submit-button" type="submit">Save preference</button>
             <p id="form-status" class="form-status" aria-live="polite"></p>
           </div>
         </form>
       `;
     }

     function App() {
       return `
         <main id="maincontent" class="page-shell" tabindex="-1">
           <section class="panel" aria-labelledby="page-title">
             <div class="panel-header">
               <p class="eyebrow">Account settings</p>
               <h1 id="page-title">Notification preferences</h1>
               <p class="intro">Pick the channel that fits your day-to-day workflow best. You can update this preference at any time.</p>
             </div>
             <div class="panel-body">
               ${SettingsForm()}
             </div>
           </section>
         </main>
       `;
     }

     document.getElementById("app").innerHTML = App();

     const form = document.getElementById("preferences-form");
     const radios = Array.from(form.elements.namedItem("notificationPreference"));
     const fieldset = document.getElementById("notification-group");
     const errorMessage = document.getElementById("notification-error");
     const statusMessage = document.getElementById("form-status");

     function selectedPreference() {
       return radios.find((radio) => radio.checked) || null;
     }

     function setErrorState(hasError) {
       fieldset.dataset.invalid = String(hasError);
       errorMessage.hidden = !hasError;

       radios.forEach((radio) => {
         radio.setAttribute("aria-invalid", String(hasError));
       });
     }

     function clearStatus() {
       statusMessage.textContent = "";
     }

     radios.forEach((radio) => {
       radio.addEventListener("change", () => {
         if (selectedPreference()) {
           setErrorState(false);
           clearStatus();
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const selected = selectedPreference();

       if (!selected) {
         setErrorState(true);
         clearStatus();
         radios[0].focus();
         return;
       }

       setErrorState(false);
       statusMessage.textContent = `Preference saved: ${selected.value}.`;
     });
